import React, { useEffect, useRef, useState } from 'react';
import { Box, CircularProgress, Typography } from '@mui/material';

declare global {
  interface Window {
    TradingView: any;
  }
}

const TradingViewWidget: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [widget, setWidget] = useState<any>(null);

  useEffect(() => {
    let isMounted = true;

    const initializeWidget = () => {
      if (!window.TradingView || !containerRef.current || !isMounted) return;

      try {
        const widgetInstance = new window.TradingView.widget({
          autosize: true,
          symbol: 'BINANCE:BTCUSDT',
          interval: '1',
          timezone: 'Asia/Shanghai',
          theme: 'dark',
          style: '1',
          locale: 'zh_CN',
          toolbar_bg: '#f1f3f6',
          enable_publishing: false,
          allow_symbol_change: true,
          container_id: 'tradingview_widget',
          library_path: 'https://s3.tradingview.com/tv.js',
          loading_screen: true,
          debug: true
        });

        if (isMounted) {
          setWidget(widgetInstance);
          setIsLoading(false);
        }
      } catch (err) {
        console.error('TradingView initialization error:', err);
        if (isMounted) {
          setError('TradingView 组件加载失败，请刷新页面重试');
          setIsLoading(false);
        }
      }
    };

    const loadTradingViewScript = () => {
      if (window.TradingView) {
        initializeWidget();
        return;
      }

      const script = document.createElement('script');
      script.id = 'tradingview-widget-script';
      script.src = 'https://s3.tradingview.com/tv.js';
      script.async = true;

      script.onload = () => {
        if (isMounted) {
          initializeWidget();
        }
      };

      script.onerror = () => {
        console.error('Failed to load TradingView script');
        if (isMounted) {
          setError('TradingView 加载失败，请检查网络连接并刷新页面');
          setIsLoading(false);
        }
      };

      document.head.appendChild(script);
    };

    loadTradingViewScript();

    return () => {
      isMounted = false;
      if (widget) {
        try {
          widget.remove();
        } catch (err) {
          console.error('Error cleaning up TradingView widget:', err);
        }
      }
      const script = document.getElementById('tradingview-widget-script');
      if (script) {
        script.remove();
      }
    };
  }, []);

  if (error) {
    return (
      <Box
        display="flex"
        alignItems="center"
        justifyContent="center"
        height="100%"
        width="100%"
        bgcolor="#1e222d"
      >
        <Typography color="error">{error}</Typography>
      </Box>
    );
  }

  return (
    <Box position="relative" height="100%" width="100%">
      <div 
        id="tradingview_widget" 
        ref={containerRef}
        style={{ height: '100%', width: '100%' }}
      />
      {isLoading && (
        <Box
          position="absolute"
          top={0}
          left={0}
          right={0}
          bottom={0}
          display="flex"
          alignItems="center"
          justifyContent="center"
          bgcolor="#1e222d"
        >
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};

export default TradingViewWidget;